322				return nil, false
323			}
324			if runInfo.rv.Len() < numIn-indexIn {
325				runInfo.err = newStringError(callExpr, fmt.Sprintf("function wants %v arguments but received %v", numIn, numExprs+runInfo.rv.Len()-1))
