4	import (
5		"errors"
6		"fmt"
7		"reflect"
8		"strconv"
9		"strings"
10		"unicode"
11	
12		"github.com/mattn/anko/ast"
13	)
14	
15	const (
16		// EOF is short for End of file.
17		EOF = -1
18		// EOL is short for End of line.
19		EOL = '\n'
20	)
21	
