43	// opName is correction of operation names.
44	var opName = map[string]int{
45		"func":     FUNC,
46		"return":   RETURN,
47		"var":      VAR,
48		"throw":    THROW,
49		"if":       IF,
50		"for":      FOR,
51		"break":    BREAK,
52		"continue": CONTINUE,
53		"in":       IN,
54		"else":     ELSE,
