35	// Scanner stores informations for lexer.
36	type Scanner struct {
37		src      []rune
38		offset   int
39		lineHead int
40		line     int
41	}
42	
43	// opName is correction of operation names.
44	var opName = map[string]int{
45		"func":     FUNC,
46		"return":   RETURN,
47		"var":      VAR,
48		"throw":    THROW,
49		"if":       IF,
50		"for":      FOR,
51		"break":    BREAK,
52		"continue": CONTINUE,
53		"in":       IN,
54		"else":     ELSE,
55		"new":      NEW,
56		"true":     TRUE,
57		"false":    FALSE,
58		"nil":      NIL,
59		"module":   MODULE,
60		"try":      TRY,
61		"catch":    CATCH,
62		"finally":  FINALLY,
63		"switch":   SWITCH,
64		"case":     CASE,
65		"default":  DEFAULT,
66		"go":       GO,
67		"chan":     CHAN,
68		"struct":   STRUCT,
69		"make":     MAKE,
70		"type":     TYPE,
