425	func (s *Scanner) scanIdentifier() (string, error) {
426		var ret []rune
427		for {
428			if !isLetter(s.peek()) && !isDigit(s.peek()) {
429				break
430			}
431			ret = append(ret, s.peek())
432			s.next()
433		}
434		return string(ret), nil
