273	+func splitTopLevelArguments(runes []rune, separator rune) ([]string, error) {
274	+	parts := make([]string, 0)
275	+	start := 0
276	+	depthParen := 0
277	+	depthBracket := 0
278	+	depthBrace := 0
279	+	for index := 0; index < len(runes); index++ {
280	+		switch runes[index] {
281	+		case '"', '\'', '`':
282	+			next, err := scanQuotedRunes(runes, index)
283	+			if err != nil {
284	+				return nil, err
285	+			}
286	+			index = next - 1
287	+		case '#':
288	+			next := index + 1
289	+			for next < len(runes) && runes[next] != '\n' {
290	+				next++
291	+			}
292	+			index = next - 1
293	+		case '(':
294	+			depthParen++
295	+		case ')':
296	+			depthParen--
297	+		case '[':
298	+			depthBracket++
299	+		case ']':
300	+			depthBracket--
301	+		case '{':
302	+			depthBrace++
303	+		case '}':
304	+			depthBrace--
305	+		default:
306	+			if runes[index] == separator && depthParen == 0 && depthBracket == 0 && depthBrace == 0 {
307	+				parts = append(parts, string(runes[start:index]))
308	+				start = index + 1
309	+			}
310	+		}
311	+	}
312	+	parts = append(parts, string(runes[start:]))
313	+	return parts, nil
314	+}
