316	+func findTopLevelRune(runes []rune, target rune) (int, bool, error) {
317	+	depthParen := 0
318	+	depthBracket := 0
319	+	depthBrace := 0
320	+	for index := 0; index < len(runes); index++ {
321	+		switch runes[index] {
322	+		case '"', '\'', '`':
323	+			next, err := scanQuotedRunes(runes, index)
324	+			if err != nil {
325	+				return 0, false, err
326	+			}
327	+			index = next - 1
328	+		case '#':
329	+			next := index + 1
330	+			for next < len(runes) && runes[next] != '\n' {
331	+				next++
332	+			}
333	+			index = next - 1
334	+		case '(':
335	+			depthParen++
336	+		case ')':
337	+			depthParen--
338	+		case '[':
339	+			depthBracket++
340	+		case ']':
341	+			depthBracket--
342	+		case '{':
343	+			depthBrace++
344	+		case '}':
345	+			depthBrace--
346	+		default:
347	+			if runes[index] == target && depthParen == 0 && depthBracket == 0 && depthBrace == 0 {
348	+				return index, true, nil
349	+			}
350	+		}
351	+	}
352	+	return 0, false, nil
353	+}
