355	+func scanBalancedRunes(runes []rune, start int, open rune, close rune) (int, error) {
356	+	depth := 0
357	+	for index := start; index < len(runes); index++ {
358	+		switch runes[index] {
359	+		case '"', '\'', '`':
360	+			next, err := scanQuotedRunes(runes, index)
361	+			if err != nil {
362	+				return 0, err
363	+			}
364	+			index = next - 1
365	+			continue
366	+		case '#':
367	+			next := index + 1
368	+			for next < len(runes) && runes[next] != '\n' {
369	+				next++
370	+			}
371	+			index = next - 1
372	+			continue
373	+		}
374	+		if runes[index] == open {
375	+			depth++
376	+		} else if runes[index] == close {
377	+			depth--
378	+			if depth == 0 {
379	+				return index, nil
380	+			}
381	+		}
382	+	}
383	+	return 0, newDefaultArgumentError(runes, start, "invalid default argument declaration")
384	+}
