386	+func scanQuotedRunes(runes []rune, start int) (int, error) {
387	+	quote := runes[start]
388	+	index := start + 1
389	+	for index < len(runes) {
390	+		if quote != '`' && runes[index] == '\\' {
391	+			index += 2
392	+			continue
393	+		}
394	+		if runes[index] == quote {
395	+			return index + 1, nil
396	+		}
397	+		index++
398	+	}
399	+	return 0, newDefaultArgumentError(runes, start, "invalid default argument declaration")
400	+}
