38	+func rewriteDefaultArgumentFunctions(src string) (string, error) {
39	+	runes := []rune(src)
40	+	var builder strings.Builder
41	+	counter := 0
42	+	for i := 0; i < len(runes); {
43	+		switch runes[i] {
44	+		case '#':
45	+			j := i + 1
46	+			for j < len(runes) && runes[j] != '\n' {
47	+				j++
48	+			}
49	+			builder.WriteString(string(runes[i:j]))
50	+			i = j
51	+			continue
52	+		case '"', '\'', '`':
53	+			j, err := scanQuotedRunes(runes, i)
54	+			if err != nil {
55	+				return "", err
56	+			}
57	+			builder.WriteString(string(runes[i:j]))
58	+			i = j
59	+			continue
60	+		}
61	+		if hasKeywordAt(runes, i, "func") {
62	+			transformed, next, changed, err := rewriteFunctionAt(runes, i, counter)
63	+			if err != nil {
64	+				return "", err
65	+			}
66	+			if changed {
67	+				counter++
68	+			}
69	+			builder.WriteString(transformed)
70	+			i = next
71	+			continue
72	+		}
73	+		builder.WriteRune(runes[i])
74	+		i++
75	+	}
76	+	return builder.String(), nil
77	+}
