126	+func parseDefaultArgumentParams(src string) ([]defaultArgumentParam, bool, error) {
127	+	parts, err := splitTopLevelArguments([]rune(src), ',')
128	+	if err != nil {
129	+		return nil, false, err
130	+	}
131	+	params := make([]defaultArgumentParam, 0, len(parts))
132	+	hasDefaults := false
133	+	seenDefault := false
134	+	for index, part := range parts {
135	+		part = strings.TrimSpace(part)
136	+		if part == "" {
137	+			if len(parts) == 1 {
138	+				return nil, false, nil
139	+			}
140	+			return nil, false, fmt.Errorf("invalid default argument declaration")
141	+		}
142	+		param, err := parseDefaultArgumentParam(part)
143	+		if err != nil {
144	+			return nil, false, err
145	+		}
146	+		if param.IsVariadic && index != len(parts)-1 {
147	+			return nil, false, fmt.Errorf("invalid default argument declaration")
148	+		}
149	+		if param.Default != "" {
150	+			hasDefaults = true
151	+			seenDefault = true
152	+		} else if seenDefault && !param.IsVariadic {
153	+			return nil, false, fmt.Errorf("invalid default argument declaration")
154	+		}
155	+		if param.IsVariadic && param.Default != "" {
156	+			return nil, false, fmt.Errorf("invalid default argument declaration")
157	+		}
158	+		params = append(params, param)
159	+	}
160	+	return params, hasDefaults, nil
161	+}
162	+
163	+func parseDefaultArgumentParam(src string) (defaultArgumentParam, error) {
164	+	param := defaultArgumentParam{}
165	+	if strings.HasSuffix(src, "...") {
166	+		param.IsVariadic = true
167	+		src = strings.TrimSpace(strings.TrimSuffix(src, "..."))
168	+	}
169	+	equalIndex, found, err := findTopLevelRune([]rune(src), '=')
170	+	if err != nil {
171	+		return param, err
172	+	}
173	+	if found {
174	+		param.Name = strings.TrimSpace(src[:equalIndex])
175	+		param.Default = strings.TrimSpace(src[equalIndex+1:])
176	+	} else {
177	+		param.Name = strings.TrimSpace(src)
178	+	}
179	+	if !isValidIdentifier(param.Name) || (found && param.Default == "") {
180	+		return param, fmt.Errorf("invalid default argument declaration")
181	+	}
182	+	return param, nil
183	+}
