185	+func buildDefaultArgumentPrologue(params []defaultArgumentParam, argsName string) string {
186	+	var builder strings.Builder
187	+	required := 0
188	+	variadicIndex := -1
189	+	for index, param := range params {
190	+		if param.IsVariadic {
191	+			variadicIndex = index
192	+			break
193	+		}
194	+		if param.Default == "" {
195	+			required++
196	+		}
197	+	}
198	+	if variadicIndex == -1 {
199	+		builder.WriteString(" if len(")
200	+		builder.WriteString(argsName)
201	+		builder.WriteString(") > ")
202	+		builder.WriteString(fmt.Sprintf("%d", len(params)))
203	+		builder.WriteString(" { throw \"function wants ")
204	+		builder.WriteString(fmt.Sprintf("%d", len(params)))
205	+		builder.WriteString(" arguments but received \" + toString(len(")
206	+		builder.WriteString(argsName)
207	+		builder.WriteString(")) };")
208	+	}
209	+	if required > 0 {
210	+		builder.WriteString(" if len(")
211	+		builder.WriteString(argsName)
212	+		builder.WriteString(") < ")
213	+		builder.WriteString(fmt.Sprintf("%d", required))
214	+		builder.WriteString(" { throw \"function wants at least ")
215	+		builder.WriteString(fmt.Sprintf("%d", required))
216	+		builder.WriteString(" arguments but received \" + toString(len(")
217	+		builder.WriteString(argsName)
218	+		builder.WriteString(")) };")
219	+	}
220	+	for index, param := range params {
221	+		if param.IsVariadic {
222	+			builder.WriteString(" var ")
223	+			builder.WriteString(param.Name)
224	+			builder.WriteString(" = [];")
225	+			builder.WriteString(" if len(")
226	+			builder.WriteString(argsName)
227	+			builder.WriteString(") > ")
228	+			builder.WriteString(fmt.Sprintf("%d", index))
229	+			builder.WriteString(" { ")
230	+			builder.WriteString(param.Name)
231	+			builder.WriteString(" = ")
232	+			builder.WriteString(argsName)
233	+			builder.WriteString("[")
234	+			builder.WriteString(fmt.Sprintf("%d", index))
235	+			builder.WriteString(":] }")
236	+			builder.WriteString(";")
237	+			continue
238	+		}
239	+		builder.WriteString(" var ")
240	+		builder.WriteString(param.Name)
241	+		builder.WriteString(" = nil;")
242	+		if param.Default == "" {
243	+			builder.WriteString(" ")
244	+			builder.WriteString(param.Name)
245	+			builder.WriteString(" = ")
246	+			builder.WriteString(argsName)
247	+			builder.WriteString("[")
248	+			builder.WriteString(fmt.Sprintf("%d", index))
249	+			builder.WriteString("]")
250	+			builder.WriteString(";")
251	+			continue
252	+		}
253	+		builder.WriteString(" if len(")
254	+		builder.WriteString(argsName)
255	+		builder.WriteString(") > ")
256	+		builder.WriteString(fmt.Sprintf("%d", index))
257	+		builder.WriteString(" { ")
258	+		builder.WriteString(param.Name)
259	+		builder.WriteString(" = ")
260	+		builder.WriteString(argsName)
261	+		builder.WriteString("[")
262	+		builder.WriteString(fmt.Sprintf("%d", index))
263	+		builder.WriteString("] } else { ")
264	+		builder.WriteString(param.Name)
265	+		builder.WriteString(" = ")
266	+		builder.WriteString(param.Default)
267	+		builder.WriteString(" };")
268	+	}
269	+	builder.WriteString(" ")
270	+	return builder.String()
271	+}
