316	+func findTopLevelRune(runes []rune, target rune) (int, bool, error) {
317	+	depthParen := 0
318	+	depthBracket := 0
319	+	depthBrace := 0
320	+	for index := 0; index < len(runes); index++ {
321	+		switch runes[index] {
322	+		case '"', '\'', '`':
323	+			next, err := scanQuotedRunes(runes, index)
324	+			if err != nil {
325	+				return 0, false, err
326	+			}
327	+			index = next - 1
328	+		case '#':
329	+			next := index + 1
330	+			for next < len(runes) && runes[next] != '\n' {
331	+				next++
332	+			}
333	+			index = next - 1
334	+		case '(':
335	+			depthParen++
336	+		case ')':
337	+			depthParen--
338	+		case '[':
339	+			depthBracket++
340	+		case ']':
341	+			depthBracket--
342	+		case '{':
343	+			depthBrace++
344	+		case '}':
345	+			depthBrace--
346	+		default:
347	+			if runes[index] == target && depthParen == 0 && depthBracket == 0 && depthBrace == 0 {
348	+				return index, true, nil
349	+			}
350	+		}
351	+	}
352	+	return 0, false, nil
353	+}
354	+
355	+func scanBalancedRunes(runes []rune, start int, open rune, close rune) (int, error) {
356	+	depth := 0
357	+	for index := start; index < len(runes); index++ {
358	+		switch runes[index] {
359	+		case '"', '\'', '`':
360	+			next, err := scanQuotedRunes(runes, index)
361	+			if err != nil {
362	+				return 0, err
363	+			}
364	+			index = next - 1
365	+			continue
366	+		case '#':
367	+			next := index + 1
368	+			for next < len(runes) && runes[next] != '\n' {
369	+				next++
370	+			}
371	+			index = next - 1
372	+			continue
373	+		}
374	+		if runes[index] == open {
375	+			depth++
376	+		} else if runes[index] == close {
377	+			depth--
378	+			if depth == 0 {
379	+				return index, nil
380	+			}
381	+		}
382	+	}
383	+	return 0, newDefaultArgumentError(runes, start, "invalid default argument declaration")
384	+}
385	+
386	+func scanQuotedRunes(runes []rune, start int) (int, error) {
387	+	quote := runes[start]
388	+	index := start + 1
389	+	for index < len(runes) {
390	+		if quote != '`' && runes[index] == '\\' {
391	+			index += 2
392	+			continue
393	+		}
394	+		if runes[index] == quote {
395	+			return index + 1, nil
396	+		}
397	+		index++
398	+	}
399	+	return 0, newDefaultArgumentError(runes, start, "invalid default argument declaration")
400	+}
401	+
402	+func hasKeywordAt(runes []rune, index int, keyword string) bool {
403	+	keywordRunes := []rune(keyword)
404	+	if index+len(keywordRunes) > len(runes) {
405	+		return false
406	+	}
407	+	for i := range keywordRunes {
408	+		if runes[index+i] != keywordRunes[i] {
409	+			return false
410	+		}
411	+	}
412	+	if index > 0 && (isLetter(runes[index-1]) || isDigit(runes[index-1])) {
413	+		return false
414	+	}
415	+	end := index + len(keywordRunes)
416	+	if end < len(runes) && (isLetter(runes[end]) || isDigit(runes[end])) {
417	+		return false
418	+	}
419	+	return true
420	+}
421	+
422	+func isValidIdentifier(name string) bool {
423	+	if name == "" {
424	+		return false
425	+	}
426	+	runes := []rune(name)
427	+	if !isLetter(runes[0]) {
428	+		return false
429	+	}
430	+	for _, ch := range runes[1:] {
431	+		if !isLetter(ch) && !isDigit(ch) {
432	+			return false
433	+		}
434	+	}
435	+	return true
436	+}
