438	+func newDefaultArgumentError(runes []rune, index int, message string) error {
439	+	line := 1
440	+	column := 1
441	+	for i := 0; i < index && i < len(runes); i++ {
442	+		if runes[i] == '\n' {
443	+			line++
444	+			column = 1
445	+		} else {
446	+			column++
447	+		}
448	+	}
449	+	return &Error{Message: message, Pos: ast.Position{Line: line, Column: column}, Fatal: true}
450	+}
