402	+func hasKeywordAt(runes []rune, index int, keyword string) bool {
403	+	keywordRunes := []rune(keyword)
404	+	if index+len(keywordRunes) > len(runes) {
405	+		return false
406	+	}
407	+	for i := range keywordRunes {
408	+		if runes[index+i] != keywordRunes[i] {
409	+			return false
410	+		}
411	+	}
412	+	if index > 0 && (isLetter(runes[index-1]) || isDigit(runes[index-1])) {
413	+		return false
414	+	}
415	+	end := index + len(keywordRunes)
416	+	if end < len(runes) && (isLetter(runes[end]) || isDigit(runes[end])) {
417	+		return false
418	+	}
419	+	return true
420	+}
421	+
422	+func isValidIdentifier(name string) bool {
423	+	if name == "" {
424	+		return false
425	+	}
426	+	runes := []rune(name)
427	+	if !isLetter(runes[0]) {
428	+		return false
429	+	}
430	+	for _, ch := range runes[1:] {
431	+		if !isLetter(ch) && !isDigit(ch) {
432	+			return false
433	+		}
434	+	}
435	+	return true
436	+}
