79	+func rewriteFunctionAt(runes []rune, start int, counter int) (string, int, bool, error) {
80	+	index := start + len("func")
81	+	for index < len(runes) && unicode.IsSpace(runes[index]) {
82	+		index++
83	+	}
84	+	for index < len(runes) && runes[index] != '(' {
85	+		index++
86	+	}
87	+	if index >= len(runes) {
88	+		return "", 0, false, newDefaultArgumentError(runes, start, "invalid default argument declaration")
89	+	}
90	+	paramEnd, err := scanBalancedRunes(runes, index, '(', ')')
91	+	if err != nil {
92	+		return "", 0, false, err
93	+	}
94	+	if _, found, err := findTopLevelRune(runes[index+1:paramEnd], '='); err != nil {
95	+		return "", 0, false, newDefaultArgumentError(runes, start, err.Error())
96	+	} else if !found {
97	+		bodyStart := paramEnd + 1
98	+		for bodyStart < len(runes) && unicode.IsSpace(runes[bodyStart]) {
99	+			bodyStart++
100	+		}
101	+		if bodyStart >= len(runes) || runes[bodyStart] != '{' {
102	+			return "", 0, false, newDefaultArgumentError(runes, start, "invalid default argument declaration")
103	+		}
104	+		return string(runes[start : bodyStart+1]), bodyStart + 1, false, nil
105	+	}
106	+	params, hasDefaults, err := parseDefaultArgumentParams(string(runes[index+1 : paramEnd]))
107	+	if err != nil {
108	+		return "", 0, false, newDefaultArgumentError(runes, start, err.Error())
109	+	}
110	+	bodyStart := paramEnd + 1
111	+	for bodyStart < len(runes) && unicode.IsSpace(runes[bodyStart]) {
112	+		bodyStart++
113	+	}
114	+	if bodyStart >= len(runes) || runes[bodyStart] != '{' {
115	+		return "", 0, false, newDefaultArgumentError(runes, start, "invalid default argument declaration")
116	+	}
117	+	if !hasDefaults {
118	+		return string(runes[start : bodyStart+1]), bodyStart + 1, false, nil
119	+	}
120	+	internalName := fmt.Sprintf("__anko_default_args_%d", counter)
121	+	prefix := string(runes[start:index])
122	+	suffix := string(runes[paramEnd+1 : bodyStart+1])
123	+	return prefix + "(" + internalName + "...)" + suffix + buildDefaultArgumentPrologue(params, internalName), bodyStart + 1, true, nil
124	+}
