355	+func scanBalancedRunes(runes []rune, start int, open rune, close rune) (int, error) {
356	+	depth := 0
357	+	for index := start; index < len(runes); index++ {
358	+		switch runes[index] {
359	+		case '"', '\'', '`':
360	+			next, err := scanQuotedRunes(runes, index)
361	+			if err != nil {
362	+				return 0, err
363	+			}
364	+			index = next - 1
365	+			continue
366	+		case '#':
367	+			next := index + 1
368	+			for next < len(runes) && runes[next] != '\n' {
369	+				next++
370	+			}
371	+			index = next - 1
372	+			continue
373	+		}
374	+		if runes[index] == open {
375	+			depth++
376	+		} else if runes[index] == close {
377	+			depth--
378	+			if depth == 0 {
379	+				return index, nil
380	+			}
381	+		}
382	+	}
383	+	return 0, newDefaultArgumentError(runes, start, "invalid default argument declaration")
384	+}
385	+
386	+func scanQuotedRunes(runes []rune, start int) (int, error) {
387	+	quote := runes[start]
388	+	index := start + 1
389	+	for index < len(runes) {
390	+		if quote != '`' && runes[index] == '\\' {
391	+			index += 2
392	+			continue
393	+		}
394	+		if runes[index] == quote {
395	+			return index + 1, nil
396	+		}
397	+		index++
398	+	}
399	+	return 0, newDefaultArgumentError(runes, start, "invalid default argument declaration")
400	+}
