422	+func isValidIdentifier(name string) bool {
423	+	if name == "" {
424	+		return false
425	+	}
426	+	runes := []rune(name)
427	+	if !isLetter(runes[0]) {
428	+		return false
429	+	}
430	+	for _, ch := range runes[1:] {
431	+		if !isLetter(ch) && !isDigit(ch) {
432	+			return false
433	+		}
434	+	}
435	+	return true
436	+}
